class Solution { struct Node{int child[2]={};int count=0;};vector<Node> trie{{}};void update(int value,int delta){int node=0;for(int bit=20;bit>=0;--bit){int direction=value>>bit&1;if(!trie[node].child[direction]){trie[node].child[direction]=trie.size();trie.push_back({});}node=trie[node].child[direction];trie[node].count+=delta;}}int query(int value){int node=0,result=0;for(int bit=20;bit>=0;--bit){int direction=value>>bit&1,preferred=direction^1,next=trie[node].child[preferred];if(next&&trie[next].count>0){result|=1<<bit;node=next;}else node=trie[node].child[direction];}return result;}public:int maximumStrongPairXor(vector<int>& nums){sort(nums.begin(),nums.end());int answer=0,left=0;for(int value:nums){update(value,1);while(2LL*nums[left]<value)update(nums[left++],-1);answer=max(answer,query(value));}return answer;} };
